import{_ as r,c as t,o as n,a2 as o}from"./chunks/framework.PGES7OoM.js";const c=JSON.parse('{"title":"Curvy for users","description":"","frontmatter":{"rawMarkdown":"# Curvy for users\\n\\nThe Curvy App is a privacy-first application that provides a familiar set of features, similar to any crypto wallet.\\n\\nThis quick-start guide walks you through setting up your wallet and Curvy ID, as well as receiving and sending assets privately. Start with any step, or follow them in order for the full experience.\\n\\n> [!TIP]\\n> To see how Curvy works under the hood, read the [Curvy for the Curious section](../for-the-curious/index.md).\\n> <br>\\n> To start developing right away with the Curvy SDK, refer to [Curvy for Programmers](../for-programmers/installing-the-sdk).\\n\\n## Supported networks and tokens\\n\\nCurvy currently supports:\\n\\n- ETH\\n- WETH\\n- USDT\\n- WBTC\\n- USDC\\n- USDC.e\\n- SOL\\n- PathUSD\\n- USDG\\n\\non the following networks:\\n\\n- Arbitrum\\n- Base\\n- Ethereum\\n- Optimism\\n- Polygon\\n- Binance Smart Chain\\n- Linea\\n- Gnosis\\n- Solana\\n- Tempo\\n- Robinhood Chain\\n\\n> [!TIP]\\n> You can also play around with Curvy on the Sepolia testnet. Turn on **Enable test networks** under **Settings → Advanced settings**, then use the network menu to switch between Mainnet and Testnet.\\n","rawMarkdownPath":"/_raw/for-users/index.md","rawMarkdownTitle":"Curvy for users","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/index.md"},"headers":[],"relativePath":"for-users/index.md","filePath":"for-users/index.md","lastUpdated":1791449043000}'),i={name:"for-users/index.md"};function a(s,e,l,u,d,p){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="curvy-for-users" tabindex="-1">Curvy for users <a class="header-anchor" href="#curvy-for-users" aria-label="Permalink to &quot;Curvy for users&quot;">​</a></h1><p>The Curvy App is a privacy-first application that provides a familiar set of features, similar to any crypto wallet.</p><p>This quick-start guide walks you through setting up your wallet and Curvy ID, as well as receiving and sending assets privately. Start with any step, or follow them in order for the full experience.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>To see how Curvy works under the hood, read the <a href="./../for-the-curious/">Curvy for the Curious section</a>. <br> To start developing right away with the Curvy SDK, refer to <a href="./../for-programmers/installing-the-sdk.html">Curvy for Programmers</a>.</p></div><h2 id="supported-networks-and-tokens" tabindex="-1">Supported networks and tokens <a class="header-anchor" href="#supported-networks-and-tokens" aria-label="Permalink to &quot;Supported networks and tokens&quot;">​</a></h2><p>Curvy currently supports:</p><ul><li>ETH</li><li>WETH</li><li>USDT</li><li>WBTC</li><li>USDC</li><li>USDC.e</li><li>SOL</li><li>PathUSD</li><li>USDG</li></ul><p>on the following networks:</p><ul><li>Arbitrum</li><li>Base</li><li>Ethereum</li><li>Optimism</li><li>Polygon</li><li>Binance Smart Chain</li><li>Linea</li><li>Gnosis</li><li>Solana</li><li>Tempo</li><li>Robinhood Chain</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>You can also play around with Curvy on the Sepolia testnet. Turn on <strong>Enable test networks</strong> under <strong>Settings → Advanced settings</strong>, then use the network menu to switch between Mainnet and Testnet.</p></div>',10)])])}const f=r(i,[["render",a]]);export{c as __pageData,f as default};
